var stoneGameIII = function(stoneValue) {
    const n = stoneValue.length;
    const dp = Array(n);

    const dfs = (pos) => {
        if (pos >= n) return 0;
        if (dp[pos] !== undefined) return dp[pos];

        let sum = stoneValue[pos] - dfs(pos + 1);
        if (pos + 1 < n) {
            sum = Math.max(
                sum,
                stoneValue[pos] + stoneValue[pos + 1] - dfs(pos + 2),
            );
        }
        if (pos + 2 < n) {
            sum = Math.max(
                sum,
                stoneValue[pos] + stoneValue[pos + 1] + stoneValue[pos + 2] - dfs(pos + 3),
            );
        }

        dp[pos] = sum;
        return sum;
    }
    dfs(0);

    return dp[0] === 0 ? 'Tie' : dp[0] > 0 ? 'Alice' : 'Bob';
};

